test=r'''#!/usr/bin/env node
import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';import{fileURLToPath}from'node:url';import{registry,ledger}from'../tools/build-counter-selector-wave-08.mjs';import{check}from'../tools/validate-counter-selector-wave-08.mjs';const R=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),J=p=>JSON.parse(fs.readFileSync(path.join(R,p),'utf8')),Q=x=>structuredClone(x),c0=J('data/project/counter-selector-wave-08-blind-review.json'),p0=J(c0.parent_packet_registry_path),pm0=J(c0.parent_release_path);const M=[(c,p,r,l)=>r.counts.identity_minimized_packets_reviewed++,(c,p,r,l)=>r.counts.procedurally_separated_review_passes++,(c,p,r,l)=>r.counts.bounded_dimension_supports++,(c,p,r,l)=>r.counts.mechanism_only_packets++,(c,p,r,l)=>r.counts.disagreements_preserved++,(c,p,r,l)=>r.counts.analysis_class_recommendations++,(c,p,r,l)=>r.counts.field_test_eligible_packets++,(c,p,r,l)=>r.counts.operator_findings++,(c,p,r,l)=>r.records.pop(),(c,p,r,l)=>l.records.pop(),(c,p,r,l)=>r.records[0].packet_id='CS-BLIND-9999-B02',(c,p,r,l)=>r.records[0].parent_attribution_class='system_mechanism',(c,p,r,l)=>delete r.records[0].dimension_vector.custody,(c,p,r,l)=>r.records[0].review_passes.pop(),(c,p,r,l)=>r.records[0].review_passes[0].fresh_identity_minimized_context=false,(c,p,r,l)=>r.records[0].review_passes[0].external_independence_claimed=true,(c,p,r,l)=>r.records[0].field_test_eligible=true,(c,p,r,l)=>r.records[0].operator_finding=true,(c,p,r,l)=>r.records[0].promotion_generated=true,(c,p,r,l)=>r.records[0].person_ranking_generated=true,(c,p,r,l)=>r.records[0].public_identity_release_authorized=true,(c,p,r,l)=>r.records[0].graph_effect='edge',(c,p,r,l)=>r.records[0].bounded_support_count=3,(c,p,r,l)=>r.records[2].bounded_support_count=1,(c,p,r,l)=>r.records[2].dimension_vector.custody='bounded_support',(c,p,r,l)=>r.records[2].mechanism_observations.partnership_capacity_established=true,(c,p,r,l)=>r.records[0].analysis_class_recommendation.historical_row_rewritten=true,(c,p,r,l)=>r.records[0].candidate_id='CS-C0012',(c,p,r,l)=>c.boundaries.procedural_separation_is_external_independence=true,(c,p,r,l)=>c.boundaries.collective_packet_is_individual_operator_finding=true,(c,p,r,l)=>c.boundaries.system_mechanism_is_person_or_partnership=true,(c,p,r,l)=>c.boundaries.review_result_authorizes_field_test=true];let n=0;for(let f of M){let c=Q(c0),p=Q(p0),pm=Q(pm0),r=registry(c,p,pm),l=ledger(c,r);f(c,p,r,l);assert.throws(()=>check(c,p,r,l));n++}assert.equal(n,32);console.log('wave08 mutations PASS',n);
'''
W('test/counter-selector-wave-08.test.js',test)
os.system('node tools/build-counter-selector-wave-08.mjs')
